export const officialContests: Contest[] = baseOfficialContests.map((contest) => {
  const municipalityIdentity = municipalityIdentityByOrganization[contest.organization] ?? {}
  const merged = { ...contest, ...planOverrides[contest.id], ...municipalityIdentity }
  return merged.studyReference ? merged : { ...merged, subjects: [] }
})
